/**
 * @distilled.cloud/rivet -- Rivet engine API SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy models
 * that `scripts/convert.ts` converts from the OpenAPI document mirrored at
 * `specs/spec-mirror-rivet/specs/openapi.json`. Everything else in this
 * folder is hand-written.
 *
 * One module per API area: `actors`, `auth`, `datacenters`, `metadata`,
 * `namespaces` and `pools`. The same API serves Rivet Cloud and every
 * self-hosted control plane; configure the endpoint on the credentials.
 *
 * @example
 * ```ts
 * import * as Rivet from "@distilled.cloud/rivet";
 *
 * const pool = yield* Rivet.pools.upsertPool({ pool: "default", namespace: "default" });
 * ```
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export { RivetProtocol, type RivetOpError, type RivetOpContext } from "./protocol.ts";
export { paginateCursor } from "./pagination.ts";
export * as Retry from "./retry.ts";
export * from "./services/index.ts";
